package iq.yasserapps.studio;
import java.io.*;import java.util.*;import java.util.zip.*;import java.nio.charset.StandardCharsets;import java.util.regex.*;
public final class WindowInventory {
 static final Pattern HINT=Pattern.compile("update available|check.?update|optional.?update|telegram|t\\.me/|subscribe|don't show again|تحديث|اشتراك|تيليجرام",Pattern.CASE_INSENSITIVE);
 public static String inspect(File f)throws IOException{Map<String,Integer> counts=new LinkedHashMap<>();StringBuilder hits=new StringBuilder();int listed=0,skipped=0;long budget=160L*1024*1024;Set<String> seen=new HashSet<>();try(ZipFile z=new ZipFile(f)){Enumeration<? extends ZipEntry> es=z.entries();while(es.hasMoreElements()){ZipEntry e=es.nextElement();ApkEngine.valid(e,seen);if(e.isDirectory())continue;String n=e.getName(),low=n.toLowerCase(Locale.ROOT);String kind=low.matches("classes([0-9]+)?\\.dex")?"DEX":low.endsWith(".smali")?"Smali":low.equals("resources.arsc")?"ARSC":low.endsWith(".xml")?"XML":low.startsWith("lib/")&&low.endsWith(".so")?"Native":low.startsWith("assets/")||low.endsWith(".json")?"Assets/JSON":null;if(kind==null)continue;counts.put(kind,counts.getOrDefault(kind,0)+1);if(e.getSize()>32L*1024*1024||e.getSize()>budget){skipped++;continue;}byte[] data=ApkEngine.read(z,e,32L*1024*1024);budget-=data.length;boolean found=HINT.matcher(new String(data,StandardCharsets.UTF_8)).find();if(!found&&("XML".equals(kind)||"ARSC".equals(kind)))found=HINT.matcher(new String(data,StandardCharsets.UTF_16LE)).find();if(found&&listed++<100)hits.append(kind).append(": ").append(n).append('\n');}}
 return "فحص مصادر متعدد (مؤشرات نصية وليست إثباتاً لمنطق التنفيذ)\n"+counts+"\nملفات تجاوزت حد الفحص: "+skipped+"\nملفات تحمل مؤشرات: "+listed+"\n"+hits;}
}